/* A colour packed as 0xAARRGGBB; the channels are taken from 0 to 1, as everywhere else */
static MOD_UNUSED uint32_t font_rgba(float r, float g, float b, float a) {
    const float channel[4] = { a, r, g, b };
    uint32_t out = 0;
    int at;
    for (at = 0; at < 4; ++at) {
        int value = (int)(channel[at] * 255.0f + 0.5f);
        if (value < 0) value = 0;
        if (value > 255) value = 255;
        out = (out << 8) | (uint32_t)value;
    }
    return out;
}

/* The fonts this mod made, kept by the name the sheet gave them */
enum { kModFonts = 8 };
static char g_font_named[kModFonts][32];
static AmodFontId g_font_id[kModFonts];

static MOD_UNUSED int font_slot(const char* name) {
    int at;
    for (at = 0; at < kModFonts; ++at)
        if (g_font_named[at][0] != 0 && strcmp(g_font_named[at], name) == 0) return at;
    return -1;
}

static MOD_UNUSED AmodFontId font_mine(const char* name) {
    const int slot = font_slot(name);
    return slot >= 0 ? g_font_id[slot] : AMOD_FONT_NONE;
}

static MOD_UNUSED AmodFontId font_make(const char* name) {
    AmodFontId id = font_mine(name);
    int at;
    if (API->spriteFont == 0 || name == 0 || name[0] == 0) return AMOD_FONT_NONE;
    if (id != AMOD_FONT_NONE) return id;

    id = API->spriteFont->Create(SELF, name);
    if (id == AMOD_FONT_NONE) return AMOD_FONT_NONE;
    for (at = 0; at < kModFonts; ++at) {
        if (g_font_named[at][0] != 0) continue;
        if (strlen(name) >= sizeof g_font_named[0]) break;
        strcpy(g_font_named[at], name);
        g_font_id[at] = id;
        break;
    }
    return id;
}

/* Ours first, the game's after: a sheet writes one name and gets whichever exists */
static MOD_UNUSED AmodFontId font_any(const char* name) {
    const AmodFontId mine = font_mine(name);
    if (mine != AMOD_FONT_NONE) return mine;
    return API->spriteFont != 0 ? API->spriteFont->FromGame(SELF, name) : AMOD_FONT_NONE;
}

static MOD_UNUSED void font_forget(const char* name) {
    const int slot = font_slot(name);
    if (slot < 0 || API->spriteFont == 0) return;
    API->spriteFont->Destroy(SELF, g_font_id[slot]);
    g_font_named[slot][0] = 0;
    g_font_id[slot] = AMOD_FONT_NONE;
}

/* The picture a glyph is cut from lives in the game or in a file, the same way menu pictures do */
static MOD_UNUSED AmodTextureId font_texture(const char* path) {
    AmodTextureId id;
    if (API->textures == 0 || path == 0 || path[0] == 0) return AMOD_INVALID_TEXTURE;
    id = API->textures->Find(SELF, path);
    if (id == AMOD_INVALID_TEXTURE) id = API->textures->Load(SELF, path, 0, 1);
    return id;
}

static MOD_UNUSED void font_grid(const char* name, const char* file, const char* chars,
                                 float cell_w, float cell_h, float offset_x) {
    const AmodFontId id = font_make(name);
    const AmodTextureId texture = font_texture(file);
    if (id == AMOD_FONT_NONE || texture == AMOD_INVALID_TEXTURE) return;
    API->spriteFont->SetGrid(SELF, id, texture, chars, cell_w, cell_h, offset_x);
}

static MOD_UNUSED void font_glyph(const char* name, int ch, const char* file, float x, float y,
                                  float w, float h, float offset_x, float offset_y) {
    const AmodFontId id = font_make(name);
    const AmodTextureId texture = font_texture(file);
    if (id == AMOD_FONT_NONE || texture == AMOD_INVALID_TEXTURE) return;
    API->spriteFont->SetGlyph(SELF, id, ch, texture, x, y, w, h, offset_x, offset_y);
}

static MOD_UNUSED float font_measure(const char* name, const char* text, float scale) {
    const AmodFontId id = font_any(name);
    if (id == AMOD_FONT_NONE || API->spriteFont == 0) return 0.0f;
    return API->spriteFont->Measure(SELF, id, text, scale);
}

static MOD_UNUSED float font_line_height(const char* name) {
    const AmodFontId id = font_any(name);
    if (id == AMOD_FONT_NONE || API->spriteFont == 0) return 0.0f;
    return API->spriteFont->GetLineHeight(SELF, id);
}

static MOD_UNUSED const char* font_game_name(int index) {
    const char* name = API->spriteFont != 0 ? API->spriteFont->GameFontName(SELF, index) : 0;
    return name != 0 ? name : "";
}
